#!/bin/sh
# Prints the Homebrew formula for a release, from its SHA256SUMS:
#   scripts/homebrew-formula.sh v0.1.0-alpha.4 > ../homebrew-lore/Formula/lore.rb
set -eu
tag=${1:?usage: scripts/homebrew-formula.sh <tag>}
repo=apisandipas/lore
url=https://github.com/$repo/releases/download/$tag
sums=$(curl -fsSL "$url/SHA256SUMS")
sum() { printf '%s\n' "$sums" | grep " lore-$1.tar.gz\$" | cut -d' ' -f1; }

cat <<RUBY
# Generated by scripts/homebrew-formula.sh in $repo; edit that, not this.
class Lore < Formula
  desc "Typed project notes linked to the code they govern"
  homepage "https://apisandipas.github.io/lore/"
  version "${tag#v}"
  license "MIT"

  on_macos do
    on_arm do
      url "$url/lore-darwin-arm64.tar.gz"
      sha256 "$(sum darwin-arm64)"
    end
    on_intel do
      url "$url/lore-darwin-x64.tar.gz"
      sha256 "$(sum darwin-x64)"
    end
  end

  on_linux do
    on_arm do
      url "$url/lore-linux-arm64.tar.gz"
      sha256 "$(sum linux-arm64)"
    end
    on_intel do
      url "$url/lore-linux-x64.tar.gz"
      sha256 "$(sum linux-x64)"
    end
  end

  # lore finds citations with ripgrep.
  depends_on "ripgrep"

  def install
    bin.install "lore"
  end

  test do
    assert_equal version.to_s, shell_output("#{bin}/lore --version").strip
    system "git", "init", "-q"
    system bin/"lore", "init"
    system bin/"lore", "new", "Spec", "Due dates"
    assert_match "no problems", shell_output("#{bin}/lore check")
  end
end
RUBY
